# Generated from the verified Steam data snapshot. Runtime game files are not required for these catalogs.
# UTF-8 text is compressed only to keep the module compact.
import base64
import json
import zlib

def _decode(value):
    return zlib.decompress(base64.b64decode(value), -15).decode("utf-8-sig")

EMBEDDED_PANDORA_EVENTS_XML = _decode("")
EMBEDDED_TECH_LOCALE_CSV = _decode("")
EMBEDDED_TECH_TREE_FILES = {
    "default_techtree.csv": _decode(""),
    "dlc_temples_techtree.csv": _decode(""),
    "fortresses_techtree.csv": _decode(""),
    "mountain_techtree.csv": _decode(""),
    "underground_techtree.csv": _decode(""),
    "ww_dlc_techtree.csv": _decode(""),
}


# Structure catalog metadata from the verified Steam Levels snapshot.
# Each item: filename, width, height, valid_header, source_file_size.
EMBEDDED_STRUCTURE_CATALOG = json.loads(_decode(''))
